{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "길에 버려진 자전거 처분과 자전거 등록 업무를 시와 구청 중 어느 기관이 담당하는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자전거 등록 업무와 무단방치자전거(길에 버려진 자전거) 처분 업무는 구청(자치구청장)이 담당한다. 조례 제3조제5항은 자치구청장이 자전거등록업무, 무단방치자전거의 처분 등의 업무를 성실히 수행하여야 한다고 정하고 있다.",
          "b_ids": "자전거:제3조제5항"
        },
        {
          "a_text": "시장은 자전거 등록에 필요한 계획 수립·시행과 등록 시스템 구축을 위해 노력할 의무가 있고, 자치구의 협조가 필요한 경우 구청장이 협조하도록 되어 있다. 다만 등록 업무 자체의 수행 주체는 구청이다.",
          "b_ids": "자전거:제3조제7항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
